import{_ as i,c as n,o as a,ag as t}from"./chunks/framework.Vyheyqg9.js";const d=JSON.parse('{"title":"What are the common pitfalls when applying a design pattern?","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/Coding_principles_patterns_conventions/What_are_the_common_pitfalls_when_applying_a_design_pattern.md","filePath":"senior_growth/Coding_principles_patterns_conventions/What_are_the_common_pitfalls_when_applying_a_design_pattern.md"}'),s={name:"senior_growth/Coding_principles_patterns_conventions/What_are_the_common_pitfalls_when_applying_a_design_pattern.md"};function r(o,e,l,p,c,h){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="what-are-the-common-pitfalls-when-applying-a-design-pattern" tabindex="-1">What are the common pitfalls when applying a design pattern? <a class="header-anchor" href="#what-are-the-common-pitfalls-when-applying-a-design-pattern" aria-label="Permalink to “What are the common pitfalls when applying a design pattern?”">​</a></h1><h2 id="⚠️-common-pitfalls-when-applying-design-patterns-in-javascript" tabindex="-1"><span class="hub-section-number">1 </span>Common Pitfalls When Applying Design Patterns in JavaScript <a class="header-anchor" href="#⚠️-common-pitfalls-when-applying-design-patterns-in-javascript" aria-label="Permalink to “1 Common Pitfalls When Applying Design Patterns in JavaScript”">​</a></h2><p>Design patterns are powerful tools, but <strong>misusing them can introduce complexity, reduce maintainability, or hurt performance</strong>. Here’s a detailed overview of common pitfalls to avoid.</p><hr><h2 id="_1️⃣-overengineering-premature-optimization" tabindex="-1"><span class="hub-section-number">2 </span>Overengineering / Premature Optimization <a class="header-anchor" href="#_1️⃣-overengineering-premature-optimization" aria-label="Permalink to “2 Overengineering / Premature Optimization”">​</a></h2><ul><li>Applying patterns <strong>before there’s a real need</strong>.</li><li>Example: Using Observer or Decorator for a small component that doesn’t require dynamic behavior.</li><li><strong>Consequence:</strong> Extra abstraction makes code harder to read, maintain, and debug.</li></ul><p><strong>Tip:</strong></p><blockquote><p>Only introduce a pattern when there’s a clear requirement or recurring problem.</p></blockquote><hr><h2 id="_2️⃣-misusing-inheritance-instead-of-composition" tabindex="-1"><span class="hub-section-number">3 </span>Misusing Inheritance Instead of Composition <a class="header-anchor" href="#_2️⃣-misusing-inheritance-instead-of-composition" aria-label="Permalink to “3 Misusing Inheritance Instead of Composition”">​</a></h2><ul><li>Over-reliance on class hierarchies can lead to: <ul><li>Deep, rigid inheritance trees</li><li>Fragile base classes where changes propagate unexpectedly</li></ul></li><li>Example: A “Bird” class with subclasses like “Penguin” violating LSP (cannot fly).</li></ul><p><strong>Tip:</strong></p><blockquote><p>Prefer <strong>composition over inheritance</strong> for flexibility and decoupling.</p></blockquote><hr><h2 id="_3️⃣-ignoring-single-responsibility-principle" tabindex="-1"><span class="hub-section-number">4 </span>Ignoring Single Responsibility Principle <a class="header-anchor" href="#_3️⃣-ignoring-single-responsibility-principle" aria-label="Permalink to “4 Ignoring Single Responsibility Principle”">​</a></h2><ul><li>Using a pattern but packing too much functionality into a single class/object.</li><li>Example: A Singleton that handles logging, caching, and API requests all in one.</li><li><strong>Consequence:</strong> Difficult to test, extend, or replace.</li></ul><p><strong>Tip:</strong></p><blockquote><p>Keep components <strong>focused and modular</strong>. One pattern per responsibility.</p></blockquote><hr><h2 id="_4️⃣-overusing-hocs-or-decorators-in-react" tabindex="-1"><span class="hub-section-number">5 </span>Overusing HOCs or Decorators in React <a class="header-anchor" href="#_4️⃣-overusing-hocs-or-decorators-in-react" aria-label="Permalink to “5 Overusing HOCs or Decorators in React”">​</a></h2><ul><li>Excessive nesting of HOCs can lead to: <ul><li>“Wrapper hell”</li><li>Hard-to-debug component trees</li></ul></li><li>Invalid JSX illustration replaced with a valid two-step composition (the HOCs and component must be defined/imported):</li></ul><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Enhanced</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> withAuth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">withLogger</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">withTheme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(MyComponent)));</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Inside a parent render:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Enhanced</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;;</span></span></code></pre></div><p>Create the enhanced component at module scope when appropriate; recreating a component type during each render can reset subtree state.</p><p><strong>Tip:</strong></p><blockquote><p>Use <strong>hooks</strong> and composition to simplify behavior reuse instead of deep HOC chains.</p></blockquote><hr><h2 id="_5️⃣-breaking-liskov-substitution-principle-lsp" tabindex="-1"><span class="hub-section-number">6 </span>Breaking Liskov Substitution Principle (LSP) <a class="header-anchor" href="#_5️⃣-breaking-liskov-substitution-principle-lsp" aria-label="Permalink to “6 Breaking Liskov Substitution Principle (LSP)”">​</a></h2><ul><li>Creating subclasses that <strong>cannot fully replace their base classes</strong>.</li><li>Example: Subclass overriding method in a way that throws errors for valid base-class calls.</li></ul><p><strong>Tip:</strong></p><blockquote><p>Ensure <strong>subtypes respect the parent interface and behavior</strong>.</p></blockquote><hr><h2 id="_6️⃣-overcomplicating-with-patterns-for-simple-problems" tabindex="-1"><span class="hub-section-number">7 </span>Overcomplicating with Patterns for Simple Problems <a class="header-anchor" href="#_6️⃣-overcomplicating-with-patterns-for-simple-problems" aria-label="Permalink to “7 Overcomplicating with Patterns for Simple Problems”">​</a></h2><ul><li>Applying patterns like Strategy, Factory, or Observer for trivial functionality.</li><li><strong>Consequence:</strong> Code becomes harder to understand and maintain.</li></ul><p><strong>Tip:</strong></p><blockquote><p>Evaluate <strong>simplicity first</strong>, then introduce patterns gradually.</p></blockquote><hr><h2 id="_7️⃣-ignoring-immutability-with-state-patterns" tabindex="-1"><span class="hub-section-number">8 </span>Ignoring Immutability with State Patterns <a class="header-anchor" href="#_7️⃣-ignoring-immutability-with-state-patterns" aria-label="Permalink to “8 Ignoring Immutability with State Patterns”">​</a></h2><ul><li>When combining patterns with <strong>shared mutable state</strong>, it can lead to: <ul><li>Unexpected side effects</li><li>Hard-to-trace bugs in reactive apps (React, Redux)</li></ul></li><li>Example: A Decorator modifying an object’s state directly instead of returning a new object.</li></ul><p><strong>Tip:</strong></p><blockquote><p>Prefer <strong>immutable updates</strong> to avoid subtle state issues.</p></blockquote><hr><h2 id="_8️⃣-mixing-multiple-patterns-indiscriminately" tabindex="-1"><span class="hub-section-number">9 </span>Mixing Multiple Patterns Indiscriminately <a class="header-anchor" href="#_8️⃣-mixing-multiple-patterns-indiscriminately" aria-label="Permalink to “9 Mixing Multiple Patterns Indiscriminately”">​</a></h2><ul><li>Applying too many patterns together without clear boundaries.</li><li>Example: Singleton + Factory + Observer in one module without clear separation.</li><li><strong>Consequence:</strong> Increases cognitive load, debugging difficulty, and coupling.</li></ul><p><strong>Tip:</strong></p><blockquote><p>Keep patterns <strong>isolated and purposeful</strong>. Use one pattern per concern.</p></blockquote><hr><h2 id="_9️⃣-performance-pitfalls" tabindex="-1"><span class="hub-section-number">10 </span>Performance Pitfalls <a class="header-anchor" href="#_9️⃣-performance-pitfalls" aria-label="Permalink to “10 Performance Pitfalls”">​</a></h2><ul><li>Some patterns introduce <strong>extra objects, wrappers, or function calls</strong>.</li><li>Example: <ul><li>Deeply nested Decorators or HOCs in React</li><li>Observer with many subscribers firing frequently</li></ul></li><li><strong>Consequence:</strong> Can reduce performance, especially in UI rendering.</li></ul><p><strong>Tip:</strong></p><blockquote><p>Use <strong>memoization, throttling, or selective subscriptions</strong> where necessary.</p></blockquote><hr><h2 id="_10️⃣-not-considering-testing-implications" tabindex="-1"><span class="hub-section-number">11 </span>Not Considering Testing Implications <a class="header-anchor" href="#_10️⃣-not-considering-testing-implications" aria-label="Permalink to “11 Not Considering Testing Implications”">​</a></h2><ul><li>Patterns that introduce hidden state or complex interactions can make testing harder.</li><li>Example: Singleton storing global state across tests.</li><li><strong>Tip:</strong></li></ul><blockquote><p>Always design patterns with <strong>testability</strong> in mind:</p></blockquote><ul><li>Inject dependencies</li><li>Avoid global mutable state</li><li>Favor pure functions for easier unit testing</li></ul><hr><h3 id="✅-key-takeaways" tabindex="-1"><span class="hub-section-number">11.1 </span>Key Takeaways <a class="header-anchor" href="#✅-key-takeaways" aria-label="Permalink to “11.1 Key Takeaways”">​</a></h3><ol><li>Patterns are <strong>tools, not rules</strong>; apply them only when necessary.</li><li><strong>Keep it simple</strong> — don’t overcomplicate solutions.</li><li><strong>Focus on readability, maintainability, and testability.</strong></li><li>Use <strong>composition, immutability, and modular design</strong> to avoid pitfalls.</li><li>Always evaluate <strong>performance and side effects</strong>, especially in reactive apps like React.</li></ol><blockquote><p>Senior Tip: A true sign of mastery is knowing <strong>when NOT to use a pattern</strong>.</p></blockquote><h2 id="refactor-from-a-concrete-change" tabindex="-1"><span class="hub-section-number">12 </span>Refactor from a concrete change <a class="header-anchor" href="#refactor-from-a-concrete-change" aria-label="Permalink to “12 Refactor from a concrete change”">​</a></h2><p>Use <a href="./Please_describe_Strategy_design_pattern._What_are_the_valid_use_cases_for_it.html#worked-change-inject-a-shipping-quote-rule">shipping-rule Strategy</a> when algorithms change independently, <a href="./What_kind_of_creational_design_patterns_do_you_know.html#ownership-and-creation-checks">creation/ownership checks</a> when construction leaks mutable state, and <a href="./Please_describe_what_is_KISS,_DRY,_YAGNI.html#decide-what-must-change-together">DRY&#39;s domain-rule distinction</a> to avoid extracting coincidental syntax. A pattern is justified by clearer ownership or a required variation point, not by the count of patterns in a module.</p><h2 id="separate-practice" tabindex="-1"><span class="hub-section-number">13 </span>Separate practice <a class="header-anchor" href="#separate-practice" aria-label="Permalink to “13 Separate practice”">​</a></h2><p>Use the <a href="./../../practice/engineering/patterns/What_are_the_common_pitfalls_when_applying_a_design_pattern.html">focused acceptance and evidence requirements</a>. All learner practice remains outstanding.</p>`,63)])])}const u=i(s,[["render",r]]);export{d as __pageData,u as default};
